const raw = $input.first().json;
let parsed = {};
if (raw?.input) {
  try { parsed = typeof raw.input === 'string' ? JSON.parse(raw.input) : raw.input; } catch(e) { parsed = raw; }
} else { parsed = raw || {}; }
const card_id = parsed.card_id ?? parsed.cardId ?? raw?.card_id;
const parameters = parsed.parameters ?? raw?.parameters ?? [];
if (!card_id) {
  throw new Error('card_id no encontrado. RAW: ' + JSON.stringify(raw) + ' | PARSED: ' + JSON.stringify(parsed) + ' | KEYS: ' + Object.keys(raw || {}).join(','));
}
const validCards = [55707, 55705, 63163, 55773, 65209, 66727, 66793];
if (!validCards.includes(Number(card_id))) {
  throw new Error('card_id ' + card_id + ' no autorizado. Válidos: ' + validCards.join(', '));
}
return [{ json: { card_id: Number(card_id), parameters: Array.isArray(parameters) ? parameters : [] } }];

const resp = $input.first().json;
if (resp.error) return [{ json: { result: 'ERROR', error: resp.error, rows: [], count: 0 } }];
const cols = (resp.data?.cols || []).map(c => c.name);
const rows_raw = resp.data?.rows || [];
const rows = rows_raw.map(r => Object.fromEntries(cols.map((c, i) => [c, r[i]])));
return [{ json: { result: 'OK', rows, count: rows.length } }];
